package org.codex.nfsugpreview;
import java.nio.file.*;
public final class NativePresentationSceneTest {
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);int scenes=0,rejected=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"source-race-background-*.nrb")){for(Path path:files){NativeSourceSceneBinding.Source road=(e,s,b,f)->read(dir,s,".nrh"),wall=(e,s,b,f)->read(dir,s,".nwh"),proof=(e,s,b,f)->read(dir,s,".nrp");NativeRetainedScene scene=NativeRetainedScene.capture(Files.readAllBytes(path),road,wall,proof);NativePresentation box=new NativePresentation();box.enabled(true);box.active(true);byte[] pixels=new byte[153600];if(!box.publish(box.token(),scene.epoch,scene.refresh,pixels,scene)||box.latest().scene!=scene)throw new AssertionError("Scene handoff");for(int n=0;n<2;n++){box.invalidate();try{box.publish(box.token(),scene.epoch+(n==0?1:0),scene.refresh+(n==1?1:0),pixels,scene);throw new AssertionError("Mismatched scene accepted");}catch(IllegalArgumentException expected){rejected++;}}box.invalidate();if(!box.publish(box.token(),scene.epoch,scene.refresh,pixels,null)||box.latest().scene!=null)throw new AssertionError("Fallback frame rejected");scenes++;}}if(scenes!=9||rejected!=18)throw new AssertionError();System.out.println("PASS_PRESENTATION_SCENES scenes=9 mismatched_rejected=18 missing_scene_fallback=9");}
 static byte[] read(Path dir,long serial,String suffix){try{return Files.readAllBytes(dir.resolve("owner-"+serial+suffix));}catch(Exception e){throw new RuntimeException(e);}}
}
